    "openingScenario": "Manish received his corrected Class 7 Science midterm test with 14 marks deducted. He felt embarrassed, crumpled the paper into a ball, and stuffed it into his desk drawer. Four months later, three identical questions appeared on the final exam\u2014and Manish got all three wrong again.",
    "explanation": "A corrected test paper is not a scorecard; it is pure gold! It shows you the exact blueprint of how your teacher thinks and highlights the exact blind spots in your brain. Top students don't hide their mistakes; they archive them! An organized test binder where every mistake has a written correction turns your past errors into your personal cheat code for top marks.",
    "stepByStep": [
      "Get an accordion file folder or ring binder with tabs: English, Math, Science, Social Science, Languages.",
      "Whenever a test paper is returned, never crumble or discard it.",
      "The 48-Hour Autopsy: Fold a lined sheet of paper and staple it to the front of the test: the 'Error Log'.",
      "For every question where marks were lost, record: Question #, Marks Lost, Error Type (Concept / Calculation / Rush), and the Complete Correct Solution in red pen.",
      "File the test securely in its subject tab in chronological order.",
      "Before the final exam, open your binder and review only your Error Logs: this targets 100% of your real weaknesses in 30 minutes."
    ],
    "workedExample": {
      "title": "Manish's Error Goldmine",
      "scenario": "Manish archives his corrected Math papers.",
      "steps": [
        "Staples an Error Log sheet to his Term 1 Math test.",
        "Discovers 8 marks were lost to negative sign slips, not hard algebra.",
        "Writes in red: 'Rule: Always double check negative distribution in brackets!'",
        "Files paper in 'Mathematics' accordion pocket.",
        "Reviews the Error Log before Term 2 exams.",
        "Avoids negative sign slips and scores 96%."
      ],
      "takeaway": "Archiving corrected tests with red-pen error autopsies prevents you from repeating past mistakes."
    },
    "commonMistakes": [
      {
        "mistake": "Looking only at the total score, getting upset, and shoving the paper out of sight.",
        "correction": "The score matters far less than which specific questions were missed; treat every red mark as a learning clue."
      },
      {
        "mistake": "Letting test papers get torn and lost inside messy backpacks.",
        "correction": "Unfiled papers disappear; file returned tests into your master archive the very afternoon they are returned."
      }
    ],
    "decisionChecklist": [
      "Do I have a designated accordion file or binder with subject dividers?",
      "Is there an Error Log sheet stapled to the front of every returned test?",
      "Did I write out the full, correct solution for every lost mark?",
      "Are tests filed in date order ready for pre-exam review?"
    ],
