    "openingScenario": "As Dev walked past a group of older students in the corridor, one sneered sarcastically: 'Whoa Dev, look at that giant backpack, are you moving to the Himalayas forever?' The group chuckled waiting for Dev to get angry.",
    "explanation": "Teasers are like mosquitoes: they are hungry for your emotional blood! If you slap wildly or scream in tears, they get the exact drama they wanted and bite again tomorrow. But if you respond like a dull gray stone\u2014cool, bored, unbothered\u2014their joke falls completely flat and they walk away looking foolish.",
    "stepByStep": [
      "The 3-Second Freeze: When a sarcastic jab lands, do NOT shout, cry, or tense your fists. Keep your facial expression completely neutral.",
      "Technique A (The Gray Stone): Shrug slightly and say in a flat, calm monotone: 'Okay.' or 'If you say so.'",
      "Technique B (Agree with the Absurd): Smile calmly and lean into the joke: 'Yes, setting up camp on Mount Everest tonight! Save me a seat at lunch.'",
      "Technique C (The Confused Clarifier): Look at them with curious innocence: 'What makes you say that?' (Forces them to explain their cruel joke, which makes it instantly uncool).",
      "Maintain relaxed walking pace; do not run or drop your gaze to your shoes.",
      "If teasing persists, targets identity, or turns physical, document the incidents and report directly to school counseling staff."
    ],
    "workedExample": {
      "title": "Dev's Corridor Disarmament",
      "scenario": "Dev disarms the backpack tease.",
      "steps": [
        "Keeps posture tall and relaxed.",
        "Looks directly at the older boy with a slight grin.",
        "Says cheerfully: 'Yup, Everest base camp is cold, had to pack the tent! Have a good class, guys.'",
        "Keeps walking steadily toward his science room.",
        "The older boys look bewildered; nobody laughs at Dev.",
        "Teasing completely stops because Dev gave zero drama."
      ],
      "takeaway": "Agreeing cheerfully with absurd sarcasm completely deflates teasing and leaves the teaser powerless."
    },
