    "explanation": "Anyone who truly cares about you will NEVER ask you to hide things from your parents or guardians! Manipulators and predators use flattery ('You are so special and mature') and secret gifts to build a fake wall between you and the adults who protect you. Remembering the difference between a fun surprise and a toxic secret keeps you 100% safe.",
    "stepByStep": [
      "The Golden Safety Rule: Good secrets are temporary fun surprises (like planning a birthday party). Toxic secrets ask you to hide meetings, gifts, or private photos from parents.",
      "Red Flag 1 (Secrecy): 'Promise not to tell anyone, especially your mom.' (INSTANT RED ALERT).",
      "Red Flag 2 (Flattery & Isolation): 'Your parents are so strict, you can only trust me.'",
      "Red Flag 3 (Special Gifts): Giving you money, gaming items, or snacks while demanding special favors.",
      "The Immediate Exit: Step back, keep physical distance, and say firmly: 'I have to meet my family right now.'",
      "Break the Silence: Walk directly to a trusted adult in your Safe Adults Network; report the conversation completely with zero fear of punishment."
    ],
