      "Category 2 (Wants - 30% = \u20b9300): Canteen samosas, comic books, weekend ice cream with friends.",
      "Category 3 (Savings - 20% = \u20b9200): Put directly into your locked savings bank or gullak on Day 1 (Pay Yourself First!).",
      "The Envelope System: Divide physical or digital cash into 3 labeled envelopes: Needs, Wants, Savings.",
      "The Hard Stop: When the 'Wants' envelope is empty, stop spending on luxuries until the 1st of next month."
