    "whyItMatters": "Where does all your money go? Small daily leaks\u2014\u20b920 here for chips, \u20b915 for a printout, \u20b940 for a soft drink\u2014add up to hundreds of vanished rupees without you realizing it. Keeping a daily expense ledger reveals hidden financial leaks.",
