    "openingScenario": "During a Class 7 Science exhibition brainstorm, Arjun suggested: 'What if we build a model of a space habitat on Mars?' Immediately, Kabir sneered: 'That's so dumb, we can't buy rocket fuel.' The room went dead silent and nobody suggested another idea.",
    "explanation": "Creative ideas are like fragile baby green sprouts! If you step on them the instant they poke out of the soil with 'No, that's impossible', your garden dies. The secret used by Pixar, Google, and comedy writers is 'Yes, And...'. You never say 'No'; you say 'Yes! And what if we build the Mars habitat dome out of recycled clear plastic bottles?' One wild idea sparks the next breakthrough!",
    "stepByStep": [
      "Step 1 (Establish the Magic Rule): 'For the next 10 minutes, the words 'No', 'Can't', and 'Impossible' are strictly banned.'",
      "Step 2 (The Sticky Note Blitz): Every member writes wild ideas on sticky notes\u2014one idea per note; stick them rapidly on the wall.",
      "Step 3 (Deploy 'Yes, And...'): If someone suggests an extreme idea, build on it: 'Yes! And we can use colored LED lights inside to show oxygen generators!'",
      "Step 4 (Cluster Themes): Group similar sticky notes together into creative clusters (e.g. Models, Interactive Games, Visual Charts).",
      "Step 5 (Convergent Selection): Switch to evaluation mode: Vote with dot stickers on the top 2 ideas that have High Impact and Low Cost.",
      "Celebrate the collective team invention: everyone feels proud because the final idea was built together."
    ],
