    "openingScenario": "Zoya had saved \u20b93,500 in a tin box in her room over two years. Her father suggested: 'Now that you are 13, let us visit the bank and open your official Minor's Savings Account so your money earns interest safely.'",
    "explanation": "A bank is like a high-security digital castle for your wealth! Cash in a tin box loses value to inflation every year, but money in a savings bank account is insured by the government and pays you interest just for parking it there. Understanding your 11-digit Account Number and 11-character IFSC Code turns you from a cash-dependent child into an empowered member of the modern financial world.",
    "stepByStep": [
      "Choose a Bank: Visit a local public or private bank branch (e.g. SBI Pehla Kadam / Pehli Udaan, PNB Junior, ICICI Young Stars).",
      "Gather KYC Dossier: Assemble: 1. Student Aadhaar Card & School ID, 2. Guardian Aadhaar & PAN Card, 3. Two passport-sized photographs.",
      "Complete the Form: Fill out the Account Opening Form: Name in CAPITAL letters matching Aadhaar exactly, Date of Birth, and Address.",
      "The Signature Anchor: Practice your signature carefully; this exact signature will be registered in the bank's database to verify all future withdrawals.",
      "Make Initial Deposit: Deposit starting funds (e.g. \u20b9500 or \u20b91,000) at the Cash Deposit counter with a signed Pay-In slip.",
      "Receive Credentials: Collect your official Bank Passbook containing your Account Number, IFSC Code, and Customer ID.",
      "Safety Golden Law: Never share account passwords or allow anyone else to use your passbook."
    ],
