    "openingScenario": "Manish opened his updated bank passbook and saw an entry on March 31: 'INT.PD CR: \u20b9120.00'. He thought the bank had made a mistake and added stranger's money to his account.",
    "explanation": "When you put money in a bank, you are lending your money to the bank so they can fund businesses and home loans! In return, the bank pays YOU rent for using your money\u2014that rent is called 'Interest'! When your passbook says 'INT.PD CR', it means the bank deposited earned interest into your account. Understanding how to calculate simple interest turns your money from lazy cash into an active worker earning rupees while you sleep.",
    "stepByStep": [
      "Line Entry Rule: Look at the column header: 'Dr' (Debit) means money left your account. 'Cr' (Credit) means money entered your account.",
      "The Simple Interest Formula: Interest = (P \u00d7 R \u00d7 T) \u00f7 100.",
      "P = Principal (The starting money you deposited, e.g. \u20b95,000).",
      "R = Annual Interest Rate (e.g. 4% per year on savings accounts).",
      "T = Time in years (e.g. 1 year).",
      "Do the Math: Interest = (\u20b95,000 \u00d7 4 \u00d7 1) \u00f7 100 = \u20b9200 earned for doing nothing!",
      "Quarterly Credits: Most Indian banks calculate interest on daily balances and credit it every 3 months (March, June, Sept, Dec).",
      "Verify that your final balance equals: Starting Balance + Interest Credited."
    ],
