    "explanation": "Who owns your school? Who owns the city bus or the neighborhood park swings? YOU DO! Your parents and neighbors pay taxes on every salary, every litre of petrol, and every packet of biscuits to build public facilities. When someone scratches a school desk or slashes a bus seat, they are not hurting 'the government'; they are destroying something their own parents paid for! Treating public property with fierce pride is the signature mark of a civilized citizen.",
