    "openingScenario": "At 11:45 PM on a school night, Tanmay's class WhatsApp group pinged 87 times with dancing monkey stickers, ALL-CAPS arguments about football, and a chain message: 'FORWARD TO 15 FRIENDS OR YOUR PET WILL GET SICK!' Many students woke up exhausted with headaches.",
    "explanation": "A class group chat is a shared digital classroom, not a wild 24-hour shouting bazaar! When you send a meme at 11:00 PM, you make 45 phones light up in 45 family homes. Typing in 'ALL CAPS' sounds like you are screaming at the top of your lungs. Setting clear digital etiquette rules ensures the group serves its real purpose: sharing homework assignments, project updates, and respectful peer support.",
    "stepByStep": [
      "Rule 1 (The Shouting Ban): Never type entire sentences in ALL CAPS. 'WHY DID YOU DO THAT' feels like screaming; 'Why did you do that?' is a calm question.",
      "Rule 2 (The 8:30 PM Curfew): Stop posting non-emergency messages after 8:30 PM; respect classmates' study and sleep time.",
      "Rule 3 (The Chain Spam Ban): Never forward viral chain messages ('Forward to 10 friends'); they are superstitious nonsense and digital junk.",
      "Rule 4 (Take 1-on-1 Private): If a conversation involves only you and one friend ('Are you bringing chips?'), move it to a private DM.",
      "Rule 5 (Thread Quoting): Use the swipe-to-reply quote feature so people know exactly which question you are answering.",
      "Adopt the role of a Digital Etiquette Guardian: gently remind the group: 'Hey team, let's keep this chat clear for homework questions only.'"
    ],
