    "openingScenario": "The streetlights outside Dev's housing society had been broken for 3 weeks, leaving the street pitch black and unsafe at night. Dev's family complained at the dinner table, but nobody knew who to contact to get them fixed.",
    "explanation": "A city is not run by magic; it is run by local neighborhood governance! India's cities are divided into small geographical areas called 'Wards'. Each ward elects a local representative\u2014the Ward Councillor (Parshad/Nagar Sevak)\u2014whose full-time duty is ensuring water supply, functioning streetlights, clean drains, and green parks. Your local RWA coordinates society security and cleanliness. Knowing who manages what gives you real citizen power to solve neighborhood problems.",
    "stepByStep": [
      "Step 1 (Find Your Ward): Look at your family's property tax or electricity bill to find your municipal Ward Number and Zone.",
      "Step 2 (Identify Your Ward Councillor): Search your municipal corporation website (e.g. MCD, BMC, BBMP, GHMC) to find your Councillor's name, office address, and public helpline.",
      "Step 3 (The RWA Role): Identify your local Resident Welfare Association president or secretary who manages society gates, private security, and inner compound lights.",
      "Step 4 (Draft the Civic Request): Write a formal, respectful letter stating the exact location, specific issue (e.g. '3 broken streetlights on Road 4'), safety impact, and clear photos.",
      "Step 5 (Follow Up): Submit the request to the municipal ward office or RWA desk, collect a stamped acknowledgement receipt, and follow up in 7 days."
    ],
    "workedExample": {
      "title": "Dev's Streetlight Victory",
      "scenario": "Dev tracks down his Ward Councillor.",
      "steps": [
        "Finds he lives in Ward 42, South Zone.",
        "Locates Ward Councillor's office address 500 meters from his home.",
        "Drafts a polite letter with photographs of the 3 dark lamp posts.",
        "Submits letter with his father to the Councillor's public greivance desk.",
        "Collects an acknowledgement tracking number.",
        "Municipal maintenance electricians arrive 4 days later and replace the LED bulbs.",
        "The entire street is bright, safe, and illuminated."
      ],
      "takeaway": "Knowing your local Ward Councillor and filing formal requests transforms helpless complaining into real civic solutions."
    },
