    "openingScenario": "Outside Rudra's school, a massive water-filled pothole caused two cyclists to fall and twist their ankles. Students walked past it every day grumbling, but nobody reported it to the municipal corporation.",
    "explanation": "Municipal road engineers cannot drive down every single lane of a massive city every day! They rely on vigilant citizens to be their eyes and ears. Modern cities have incredible digital tools: with the official 311 civic app or Swachhata app, you take one photo, the phone tags the exact GPS satellite coordinates, and a repair ticket is automatically assigned to the local road contractor with a 48-hour deadline to fix it. Being a civic reporter makes your city safer for everyone.",
    "stepByStep": [
      "Download the Verified App: Install your city's official municipal app (e.g. MCD 311, BMC 24x7, Swachhata-MoHUA, Namma Bengaluru).",
      "Step 1 (Safety First): Always stand on a safe pedestrian footpath when photographing road hazards; NEVER step into active vehicle traffic.",
      "Step 2 (The 2-Photo Rule): Take Photo 1 (Wide shot showing the pothole with a recognizable landmark like a shop banner) + Photo 2 (Close-up showing depth).",
      "Step 3 (Enable GPS): Ensure location services are ON so the app records the exact latitude and longitude.",
      "Step 4 (Select Category): Choose the exact department: 'Roads - Potholes' or 'Street Lighting - Bulb Out' or 'Sanitation - Garbage Dump'.",
      "Step 5 (Submit & Note Ticket): Submit the ticket and record the 8-digit Complaint Tracking ID.",
      "Check Status: Most civic apps provide before-and-after photo verification when the municipal crew completes the asphalt patch."
    ],
