    "openingScenario": "On a crowded city metro train, a 13-year-old boy wore a bulky backpack that slammed into passengers every time he turned, played mobile game sound effects on full speaker volume, and left an empty juice carton on the seat when he stepped off.",
    "explanation": "Public spaces are the living room of our nation! How you behave in a metro train car, on a park bench, or at a bus stop reveals your inner culture and character to hundreds of fellow citizens. Being a civilized commuter takes zero extra effort: plug in your earphones, take off your heavy backpack in crowds, surrender seats to elderly grandmothers, and carry your litter in your pocket. Small courtesies make our cities beautiful, peaceful, and world-class.",
